// Line-item math validation and financial precision
const invoice = $input.item.json.body || $input.item.json;
let calculatedSubtotal = 0;
if (Array.isArray(invoice.line_items)) {
  for (const item of invoice.line_items) {
    calculatedSubtotal += (Number(item.quantity) || 0) * (Number(item.unit_price) || 0);
  }
}
calculatedSubtotal = Math.round(calculatedSubtotal * 100) / 100;
const declaredSubtotal = Math.round((Number(invoice.subtotal) || 0) * 100) / 100;
const declaredTax = Math.round((Number(invoice.tax_amount) || 0) * 100) / 100;
const declaredTotal = Math.round((Number(invoice.total_amount) || 0) * 100) / 100;

const subtotalMatch = Math.abs(calculatedSubtotal - declaredSubtotal) < 0.01;
const totalMatch = Math.abs((declaredSubtotal + declaredTax) - declaredTotal) < 0.01;
const mathValid = subtotalMatch && totalMatch;

return { json: { ...invoice, subtotal: declaredSubtotal, tax_amount: declaredTax, total_amount: declaredTotal, calculated_subtotal: calculatedSubtotal, math_valid: mathValid } };

// Two-way PO Matcher & Tolerance Check
const invoice = $('Code: Validate Math & Tax').item.json;
const po = $input.item.json;
const poBudget = Number(po.total_amount || 0);
const invoiceTotal = Number(invoice.total_amount || 0);
const variance = Math.round((invoiceTotal - poBudget) * 100) / 100;
const allowableTolerance = Math.min(poBudget * 0.01, 25.0);

let matched = false;
let status = 'NO_PO_FOUND';
if (po && (po.status === 'APPROVED' || po.status === 'OPEN')) {
  if (invoice.vendor_id !== po.vendor_id) {
    status = 'VENDOR_MISMATCH';
  } else if (invoiceTotal <= poBudget) {
    matched = true;
    status = 'MATCHED_UNDER_BUDGET';
  } else if (variance <= allowableTolerance) {
    matched = true;
    status = 'MATCHED_WITHIN_TOLERANCE';
  } else {
    status = 'BUDGET_OVERRUN';
  }
}
return { json: { ...invoice, po_matched: matched, po_status: status, po_budget: poBudget, variance } };

// Anomaly & Fraud Scoring Engine
const crypto = require('crypto');
const invoice = $input.item.json;
const vendor = $('HTTP: Fetch Vendor Master').item.json;
let riskScore = 0;
const flags = [];

const fingerprint = crypto.createHash('sha256').update(`${invoice.vendor_id}::${invoice.invoice_number}`).digest('hex');

// Bank divergence check & missing/unverified bank protection
const masterBank = String(vendor.bank_account_number || '').trim();
const invoiceBank = String(invoice.bank_details?.account_number || '').trim();
if (!masterBank || !invoiceBank) {
  riskScore += 40;
  flags.push('UNVERIFIED_BANK_DETAILS');
} else if (masterBank !== invoiceBank) {
  riskScore += 80;
  flags.push('VENDOR_BANK_ACCOUNT_MISMATCH');
}

// Line-item arithmetic validation check
if (invoice.math_valid === false) {
  riskScore += 50;
  flags.push('ARITHMETIC_RECONCILIATION_FAILED');
}

// PO status check
if (!invoice.po_matched) {
  riskScore += 40;
  flags.push(`PO_${invoice.po_status}`);
}

// Threshold governance
if (invoice.total_amount >= 50000) {
  riskScore += 25;
  flags.push('CFO_APPROVAL_REQUIRED');
} else if (invoice.total_amount >= 10000) {
  riskScore += 15;
  flags.push('DIRECTOR_APPROVAL_REQUIRED');
} else if (invoice.total_amount >= 2500) {
  riskScore += 10;
  flags.push('MANAGER_APPROVAL_REQUIRED');
}

let decision = 'AUTO_APPROVED';
if (riskScore >= 70) {
  decision = 'REJECTED_FRAUD_ALERT';
} else if (riskScore >= 20 || invoice.total_amount >= 2500 || !invoice.po_matched || invoice.math_valid === false || !masterBank || !invoiceBank) {
  decision = 'MANUAL_AUDIT_REQUIRED';
}

// Strict Invariant: Math errors or unverified bank details CANNOT qualify for AUTO_APPROVED
if ((invoice.math_valid === false || !masterBank || !invoiceBank) && decision === 'AUTO_APPROVED') {
  decision = 'MANUAL_AUDIT_REQUIRED';
}

return { json: { ...invoice, fingerprint, risk_score: riskScore, decision, flags } };
